namespace AiSdk;

/// <summary>Result of a step (one model call + tool execution).</summary>
public sealed record StepResult
{
    public required int StepNumber { get; init; }

    /// <summary>Gets the content generated by the model plus the tool results.</summary>
    public required IReadOnlyList<ContentPart> Content { get; init; }

    public required FinishReason FinishReason { get; init; }

    public required Usage Usage { get; init; }

    public required LanguageModelRequest Request { get; init; }

    public ResponseMetadata? Response { get; init; }

    /// <summary>Gets the messages (assistant + tool) that this step added to the conversation.</summary>
    public required IReadOnlyList<ModelMessage> ResponseMessages { get; init; }

    public IReadOnlyList<string> Warnings { get; init; } = [];

    /// <summary>Gets the calls left pending approval in this step (<see cref="CallSettings.DeferToolApprovals"/>).</summary>
    public IReadOnlyList<ToolApprovalRequest> PendingApprovals { get; init; } = [];

    public string Text => string.Concat(Content.OfType<TextPart>().Select(p => p.Text));

    public string? ReasoningText => Content.OfType<ReasoningPart>().Any()
        ? string.Concat(Content.OfType<ReasoningPart>().Select(p => p.Text))
        : null;

    public IReadOnlyList<ToolCallPart> ToolCalls => Content.OfType<ToolCallPart>().ToList();

    public IReadOnlyList<ToolResultPart> ToolResults => Content.OfType<ToolResultPart>().ToList();

    /// <summary>Gets the sources cited in this step.</summary>
    public IReadOnlyList<SourcePart> Sources => Content.OfType<SourcePart>().ToList();
}

/// <summary>Result of <see cref="Ai.GenerateTextAsync(GenerateTextOptions)"/> or of an agent.</summary>
public sealed class GenerateTextResult
{
    private readonly Lazy<object?>? _output;

    internal GenerateTextResult(IReadOnlyList<StepResult> steps, Lazy<object?>? output)
    {
        Steps = steps;
        _output = output;
    }

    public IReadOnlyList<StepResult> Steps { get; }

    private StepResult Last => Steps[^1];

    /// <summary>Gets the text of the last step.</summary>
    public string Text => Last.Text;

    public string? ReasoningText => Last.ReasoningText;

    public IReadOnlyList<ContentPart> Content => Last.Content;

    public IReadOnlyList<ToolCallPart> ToolCalls => Last.ToolCalls;

    public IReadOnlyList<ToolResultPart> ToolResults => Last.ToolResults;

    /// <summary>Gets the calls of the last step that have no result (client tools or calls pending approval).</summary>
    public IReadOnlyList<ToolCallPart> PendingToolCalls =>
        ToolCalls.Where(c => !c.ProviderExecuted && ToolResults.All(r => r.ToolCallId != c.ToolCallId)).ToList();

    /// <summary>
    /// Gets the calls of the last step that are awaiting approval (only with
    /// <see cref="CallSettings.DeferToolApprovals"/>). Answer them with <see cref="GenerateTextOptions.ToolApprovals"/>
    /// in the next call.
    /// </summary>
    public IReadOnlyList<ToolApprovalRequest> PendingApprovals => Last.PendingApprovals;

    /// <summary>Gets the sources cited across all steps.</summary>
    public IReadOnlyList<SourcePart> Sources => Steps.SelectMany(s => s.Sources).ToList();

    public FinishReason FinishReason => Last.FinishReason;

    /// <summary>Gets the usage of the last step.</summary>
    public Usage Usage => Last.Usage;

    /// <summary>Gets the accumulated usage of all steps.</summary>
    public Usage TotalUsage => Steps.Aggregate(Usage.Empty, (acc, s) => acc + s.Usage);

    public ResponseMetadata? Response => Last.Response;

    /// <summary>Gets all the generated messages (to append to the conversation history).</summary>
    public IReadOnlyList<ModelMessage> ResponseMessages => Steps.SelectMany(s => s.ResponseMessages).ToList();

    /// <summary>Gets the structured output (if <see cref="GenerateTextOptions.Output"/> was configured).</summary>
    /// <exception cref="NoObjectGeneratedException">The final text does not conform to the schema.</exception>
    public object? Output => _output is not null ? _output.Value : throw new InvalidOperationException("No se configuró una salida estructurada (Output).");

    public T GetOutput<T>() => (T)Output!;
}

/// <summary>Result of <see cref="Ai.GenerateObjectAsync{T}"/>.</summary>
public sealed record GenerateObjectResult<T>([property: System.Diagnostics.CodeAnalysis.SuppressMessage("Naming", "CA1720:Identifier contains type name", Justification = "Mismo nombre que en el AI SDK (Output.object / result.object) para facilitar la migración.")][param: System.Diagnostics.CodeAnalysis.SuppressMessage("Naming", "CA1720:Identifier contains type name", Justification = "Ídem.")] T Object, FinishReason FinishReason, Usage Usage, ResponseMetadata? Response, string RawText);
